import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'app.dart';
// Generated by `flutterfire configure` (see docs/FIREBASE_SETUP.md). It is not
// part of this source package because it contains your own project's values.
import 'firebase_options.dart';
import 'services/firebase_auth_service.dart';
import 'services/firestore_repository.dart';
import 'services/geolocator_location_service.dart';
import 'services/local_storage_service.dart';
import 'services/notification_service.dart';
import 'services/tips_api_service.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  try {
    // Firebase must be initialised before anything that uses it.
    await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  } catch (error) {
    debugPrint('Firebase initialisation failed: $error');
    runApp(_FirebaseErrorApp(error: error));
    return;
  }

  final prefs = await SharedPreferences.getInstance();
  final repository = FirestoreRepository();

  runApp(
    SosApp(
      deps: AppDependencies(
        auth: FirebaseAuthService(),
        repository: repository,
        location: const GeolocatorLocationService(),
        tipsApi: TipsApiService(baseUrl: TipsApiService.resolveBaseUrl()),
        storage: LocalStorageService(prefs),
        notifications: FcmNotificationService(repository),
      ),
    ),
  );
}

/// Shown instead of a blank screen when Firebase is not configured correctly.
class _FirebaseErrorApp extends StatelessWidget {
  const _FirebaseErrorApp({required this.error});

  final Object error;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.cloud_off, size: 64),
                const SizedBox(height: 16),
                const Text(
                  'Firebase could not be started',
                  style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 8),
                const Text(
                  'Run "flutterfire configure" for this project and check docs/FIREBASE_SETUP.md.',
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 16),
                Text('$error', textAlign: TextAlign.center),
              ],
            ),
          ),
        ),
      ),
    );
  }
}